CREATE TABLE public.learner_profiles (user_id uuid NOT NULL, profile_role public.profile_role NOT NULL, education_level text, institution_name text, institution_id uuid REFERENCES public.institutions(id), course_name text, semester text, registration_number text, school_year text, classroom text, works boolean NOT NULL DEFAULT false, employer_name text, seeks_job boolean NOT NULL DEFAULT false, target_area text, target_position text, matching_enabled boolean NOT NULL DEFAULT false, xp integer NOT NULL DEFAULT 0, level integer NOT NULL DEFAULT 1, PRIMARY KEY(user_id,profile_role));
GRANT SELECT,INSERT,UPDATE ON public.learner_profiles TO authenticated; GRANT ALL ON public.learner_profiles TO service_role;
ALTER TABLE public.learner_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY learner_profiles_own ON public.learner_profiles FOR ALL TO authenticated USING(user_id=auth.uid() AND profile_role=public.current_profile_role() AND profile_role IN ('estudante','geral','colaborador')) WITH CHECK(user_id=auth.uid() AND profile_role=public.current_profile_role() AND profile_role IN ('estudante','geral','colaborador'));
INSERT INTO public.learner_profiles(user_id,profile_role,education_level,institution_id,target_position,matching_enabled,xp,level) SELECT id,role,education_level,institution_id,target_position,matching_enabled,xp,level FROM public.profiles WHERE role IN ('estudante','geral','colaborador');
ALTER TABLE public.employability_preferences ADD COLUMN profile_role public.profile_role NOT NULL DEFAULT 'estudante';
UPDATE public.employability_preferences e SET profile_role=p.role FROM public.profiles p WHERE p.id=e.user_id AND p.role IS NOT NULL;
ALTER TABLE public.employability_preferences DROP CONSTRAINT employability_preferences_pkey;
ALTER TABLE public.employability_preferences ADD PRIMARY KEY(user_id,profile_role);
CREATE TRIGGER preferences_profile_role BEFORE INSERT ON public.employability_preferences FOR EACH ROW EXECUTE FUNCTION public.set_learning_profile_role();
CREATE POLICY preferences_isolation ON public.employability_preferences AS RESTRICTIVE FOR ALL TO authenticated USING(profile_role=public.current_profile_role()) WITH CHECK(profile_role=public.current_profile_role());
ALTER TABLE public.behavioral_tests ADD COLUMN profile_role public.profile_role NOT NULL DEFAULT 'estudante';
UPDATE public.behavioral_tests b SET profile_role=p.role FROM public.profiles p WHERE p.id=b.user_id AND p.role IS NOT NULL;
CREATE TRIGGER behavioral_profile_role BEFORE INSERT ON public.behavioral_tests FOR EACH ROW EXECUTE FUNCTION public.set_learning_profile_role();
CREATE POLICY behavioral_isolation ON public.behavioral_tests AS RESTRICTIVE FOR ALL TO authenticated USING(profile_role=public.current_profile_role()) WITH CHECK(profile_role=public.current_profile_role());
ALTER TABLE public.notifications ADD COLUMN profile_role public.profile_role;
UPDATE public.notifications n SET profile_role=p.role FROM public.profiles p WHERE p.id=n.user_id AND p.role IS NOT NULL;
CREATE POLICY notifications_isolation ON public.notifications AS RESTRICTIVE FOR ALL TO authenticated USING(profile_role IS NULL OR profile_role=public.current_profile_role()) WITH CHECK(profile_role IS NULL OR profile_role=public.current_profile_role());
CREATE OR REPLACE FUNCTION public.configure_profile(_role public.profile_role,_details jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.profiles; org uuid; level_value text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre na sua conta'; END IF; SELECT * INTO p FROM public.profiles WHERE id=auth.uid(); IF p.role IS NOT NULL THEN RAISE EXCEPTION 'Perfil já configurado; use os acessos autorizados'; END IF; IF _role IN ('professor','colaborador') THEN RAISE EXCEPTION 'Esse perfil depende de vínculo autorizado pela organização ou Upgrade'; END IF; IF _role='estudante' THEN level_value:=_details->>'education_level'; IF level_value NOT IN ('basico','medio','graduacao','pos') OR length(trim(COALESCE(_details->>'institution_name','')))<2 THEN RAISE EXCEPTION 'Informe nível de ensino e instituição'; END IF; IF level_value IN ('graduacao','pos') AND (length(trim(COALESCE(_details->>'course_name','')))=0 OR length(trim(COALESCE(_details->>'semester','')))=0 OR length(trim(COALESCE(_details->>'registration_number','')))=0) THEN RAISE EXCEPTION 'Curso, semestre e número de matrícula são obrigatórios'; END IF; IF level_value IN ('medio','basico') AND (length(trim(COALESCE(_details->>'school_year','')))=0 OR length(trim(COALESCE(_details->>'classroom','')))=0) THEN RAISE EXCEPTION 'Série e turma são obrigatórias'; END IF; END IF;
IF _role='empresa' THEN IF length(trim(COALESCE(_details->>'organization_name','')))<2 THEN RAISE EXCEPTION 'Informe o nome da empresa'; END IF; INSERT INTO public.companies(name,code,owner_id) VALUES(trim(_details->>'organization_name'),upper(substr(md5(gen_random_uuid()::text),1,10)),auth.uid()) RETURNING id INTO org;
ELSIF _role='ies' THEN IF length(trim(COALESCE(_details->>'organization_name','')))<2 THEN RAISE EXCEPTION 'Informe o nome da instituição'; END IF; INSERT INTO public.institutions(name,owner_id) VALUES(trim(_details->>'organization_name'),auth.uid()) RETURNING id INTO org;
END IF; UPDATE public.profiles SET role=_role,company_id=CASE WHEN _role='empresa' THEN org ELSE NULL END,institution_id=CASE WHEN _role='ies' THEN org ELSE NULL END,matching_enabled=false WHERE id=auth.uid();
IF _role IN ('estudante','geral') THEN INSERT INTO public.learner_profiles(user_id,profile_role,education_level,institution_name,course_name,semester,registration_number,school_year,classroom,works,employer_name,seeks_job,target_area,target_position) VALUES(auth.uid(),_role,_details->>'education_level',_details->>'institution_name',_details->>'course_name',_details->>'semester',_details->>'registration_number',_details->>'school_year',_details->>'classroom',COALESCE((_details->>'works')::boolean,false),_details->>'employer_name',COALESCE((_details->>'seeks_job')::boolean,false),_details->>'target_area',_details->>'target_position'); END IF; END $$;
REVOKE ALL ON FUNCTION public.configure_profile(public.profile_role,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.configure_profile(public.profile_role,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.set_matching(_enabled boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.profile_role; BEGIN r:=public.current_profile_role(); IF auth.uid() IS NULL OR r NOT IN ('estudante','geral') THEN RAISE EXCEPTION 'Matching externo indisponível neste perfil'; END IF; INSERT INTO public.employability_preferences(user_id,profile_role,matching_enabled) VALUES(auth.uid(),r,_enabled) ON CONFLICT(user_id,profile_role) DO UPDATE SET matching_enabled=_enabled; INSERT INTO public.learner_profiles(user_id,profile_role,matching_enabled) VALUES(auth.uid(),r,_enabled) ON CONFLICT(user_id,profile_role) DO UPDATE SET matching_enabled=_enabled; UPDATE public.profiles SET matching_enabled=_enabled WHERE id=auth.uid(); END $$;
REVOKE ALL ON FUNCTION public.set_matching(boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.set_matching(boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.switch_test_profile(_role public.profile_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE access_row public.test_profile_access; learner public.learner_profiles; BEGIN SELECT * INTO access_row FROM public.test_profile_access WHERE user_id=auth.uid() AND role=_role; IF NOT FOUND THEN RAISE EXCEPTION 'Acesso de teste não autorizado'; END IF; IF _role IN ('estudante','geral','colaborador') THEN INSERT INTO public.learner_profiles(user_id,profile_role,institution_id) VALUES(auth.uid(),_role,access_row.institution_id) ON CONFLICT DO NOTHING; SELECT * INTO learner FROM public.learner_profiles WHERE user_id=auth.uid() AND profile_role=_role; END IF; UPDATE public.profiles SET role=_role,company_id=access_row.company_id,institution_id=access_row.institution_id,matching_enabled=COALESCE(learner.matching_enabled,false),xp=COALESCE(learner.xp,0),level=COALESCE(learner.level,1),plan='teste' WHERE id=auth.uid(); END $$;